// Full encyclopedia entries: Loire Valley. Figures (area in production, color split) from the InterLoire appellation guide 2024 (2019-2023 averages).
const LO_G = ["InterLoire, Livret des appellations des Vins de Loire 2024", "https://www.vinsdeloire.fr/sites/interloire/files/2025-11/guide-appellations-2024-bd_compressed.pdf"];
const LO_MC = ["Vins de Loire: Muscadet Sèvre et Maine crus communaux", "https://vinsdeloire.fr/en/loire-wines/muscadet-sevre-et-maine-crus-communaux"];
function lo(o) {
  const facts = [["Category", o.cat], ["Recognized", o.rec]].concat(o.facts || []);
  const sections = [["The place", `<p>${o.place}</p>`], ["The rules", `<p>${o.rules}</p>`]];
  if (o.history) sections.push(["History", `<p>${o.history}</p>`]);
  sections.push(["In the glass", `<p>${o.glass}</p>`]);
  if (o.exam) sections.push(["For the exam", `<p>${o.exam}</p>`]);
  return { lede: o.lede, facts, sections, producers: o.producers || [], sources: o.sources || [LO_G], checked: "2026-11-13" };
}

// ===== Pays Nantais =====
APXF["fr-muscadet"] = lo({ lede: "The regional Muscadet appellation, for light, dry Melon de Bourgogne from the area around Nantes near the Atlantic.", cat: "AOC, white only", rec: "1937 (modified 2021)", facts: [["Area", "About 1,270 ha (about 6,700 ha for all Muscadet appellations)"], ["Grape", "Melon de Bourgogne; Chardonnay up to 10%"]], place: "The Pays Nantais lies at the mouth of the Loire, with a cool, damp, oceanic climate. The grape, Melon de Bourgogne, came from Burgundy and spread here after the great frost of 1709, valued for its resistance to cold.", rules: "The broad regional appellation; most quality Muscadet comes from the three sub-regions. Wine kept on its lees through the winter and bottled directly from them may carry the mention 'sur lie'.", glass: "Light, crisp, saline and lemony, with low aromatics; a classic partner for oysters.", producers: ["Domaine de la Pépière", "Domaine Luneau-Papin", "Domaine de l'Écu"] });
APXF["fr-muscadet-sevre-et-maine"] = lo({ lede: "The heart of Muscadet, south-east of Nantes along the Sèvre and Maine rivers, producing most of the appellation and its finest wines.", cat: "AOC, white only; 'sur lie' and ten crus communaux", rec: "1936 (modified 2011)", facts: [["Area", "About 5,100 ha"], ["Grape", "Melon de Bourgogne"], ["Crus communaux", "Clisson, Gorges, Le Pallet (2011); Goulaine, Château-Thébaud, Monnières-Saint-Fiacre, Mouzillon-Tillières (approved 2019); La Haye-Fouassière and Vallet; Champtoceaux belongs to Muscadet Coteaux de la Loire"]], place: "The area has a complex geology from the Armorican Massif: gneiss, granite, gabbro, orthogneiss, schist and amphibolite, which growers increasingly bottle separately.", rules: "Most is sold 'sur lie', bottled after resting on its lees through the winter, which adds texture and a slight prickle. The crus communaux, defined by soil and village, require long lees ageing (well over a year) and lower yields; they were created to show that Muscadet can age and compete at a higher level.", glass: "Saline, lemony, with green apple and a mineral, sometimes smoky finish; the crus are deeper, more textured and can age ten years or more.", exam: "Know 'sur lie', Melon de Bourgogne, the three sub-regions and the first three crus (Clisson, Gorges, Le Pallet).", producers: ["Domaine de la Pépière", "Domaine Luneau-Papin", "Domaine de l'Écu", "Jo Landron", "Domaine Michel Brégeon", "Château de la Ragotière"], sources: [LO_G, LO_MC] });
function mcru(name, o) { return lo({ lede: o.lede, cat: "AOC Muscadet Sèvre et Maine with the cru communal " + name + ", white only", rec: o.rec, facts: [["Grape", "Melon de Bourgogne"], ["Soil", o.soil]], place: o.place, rules: "A cru communal of Muscadet Sèvre et Maine, with longer minimum lees ageing and lower yields than the base appellation; the wine is released well after the following spring.", glass: o.glass, producers: o.producers, sources: [LO_G, LO_MC] }); }
APXF["fr-muscadet-sevre-et-maine-clisson"] = mcru("Clisson", { rec: "2011", soil: "Granite (Clisson granite) with pebbles", lede: "One of the first three Muscadet crus communaux, on granite around the Italianate town of Clisson.", place: "Clisson lies on coarse granite where the Sèvre and Moine meet; the town was rebuilt in Italian style after the Revolution.", glass: "Rich, ripe and deep, with stone fruit and a firm mineral finish; long ageing on lees.", producers: ["Domaine Gadais", "Domaine de la Pépière"] });
APXF["fr-muscadet-sevre-et-maine-gorges"] = mcru("Gorges", { rec: "2011", soil: "Gabbro and quartz", lede: "A cru communal on gabbro, a dark igneous rock, giving austere, long-lived Muscadet.", place: "Gorges lies west of Clisson on gabbro and quartz-rich clay.", glass: "Taut, smoky and mineral, slow to open and long-lived.", producers: ["Domaine de la Pépière", "Domaine Haute Févrie", "Vignoble Poiron Dabin"] });
APXF["fr-muscadet-sevre-et-maine-le-pallet"] = mcru("Le Pallet", { rec: "2011", soil: "Gneiss, gabbro and metamorphic rock", lede: "A cru communal around Le Pallet, a village of gneiss and gabbro east of Nantes.", place: "Le Pallet lies on metamorphic rocks, gneiss and gabbro, north of Clisson; it was the birthplace of the medieval philosopher Peter Abelard.", glass: "Supple and aromatic, earlier-drinking than Clisson or Gorges.", producers: ["Domaine de la Chauvinière"] });
