// ===== Touraine =====
APXF["fr-touraine"] = lo({ lede: "The large regional appellation of Touraine, around Tours, best known for crisp Sauvignon Blanc and light reds from Gamay, Côt and Cabernet Franc, with six named sub-areas.", cat: "AOC, white, red, rosé and sparkling; six geographic names", rec: "1939 (modified 2021)", facts: [["Area", "About 4,100 ha"], ["Colors", "White 64%, red 20%, rosé 8%, sparkling 8%"], ["Grapes", "White: Sauvignon Blanc (also Chenin, Orbois, Chardonnay). Red: Gamay, Côt, Cabernet Franc, Pinot Noir"], ["Geographic names", "Amboise, Azay-le-Rideau, Chenonceaux, Mesland, Oisly, Noble-Joué"]], place: "Touraine covers the valleys of the Loire, Cher and Indre around Tours, on tuffeau, flint clay (perruches) and sand. Most Sauvignon comes from the Cher valley.", rules: "All styles. Six geographic names may be added, each with its own rules.", glass: "Crisp, grassy, citrus Sauvignon at good prices; light, fruity Gamay and Côt.", producers: ["Domaine de la Garrelière", "Domaine Les Capriades", "Domaine Thierry Puzelat", "Domaine Noëlla Morantin", "Domaine Henry Marionnet"] });
function tou(name, o) { return lo({ lede: o.lede, cat: "AOC Touraine with the geographic name " + name + ": " + o.colors, rec: o.rec || "Geographic name of Touraine", facts: [["Area", o.area], ["Grapes", o.grapes]], place: o.place, rules: o.rules || "One of six geographic names that may follow Touraine on the label, with its own grape rules.", glass: o.glass, producers: o.producers }); }
