APXF["fr-quincy"] = lo({ lede: "One of the first French appellations (1936), for Sauvignon from sandy gravel terraces west of Bourges.", cat: "AOC, white only", rec: "1936 (modified 2014)", facts: [["Area", "About 330 ha"], ["Grape", "Sauvignon Blanc (Sauvignon Gris allowed)"]], place: "Quincy lies on sand and gravel terraces of the Cher, west of Bourges.", rules: "White only. Quincy was one of the first appellations recognized in 1936, the year of Châteauneuf-du-Pape and Arbois.", glass: "Fresh, citrus, floral Sauvignon, lighter than Sancerre.", producers: ["Domaine Trotereau", "Domaine Mardon"] });
