// ===== Loire Auvergne and Forez =====
APXF["fr-saint-pourcain"] = lo({ lede: "An old vineyard in the Allier, once supplying the royal court, promoted to AOC in 2009, with the rare white grape Tressallier.", cat: "AOC, white, red and rosé", rec: "2009 (modified 2011)", facts: [["Area", "About 600 ha"], ["Colors", "Red 57%, white 30%, rosé 13%"], ["Grapes", "White: Chardonnay, Tressallier, Sauvignon. Red: Gamay, Pinot Noir"]], place: "The vineyards lie along the Sioule river in the Allier, on limestone, granite and sand.", rules: "Whites blend Chardonnay with Tressallier, a local grape related to Sacy; reds blend Gamay and Pinot Noir.", glass: "Fresh, crisp whites and light reds.", producers: ["Domaine des Bérioles", "Domaine Nebout", "Union des Vignerons de Saint-Pourçain"] });
