APXF["fr-cotes-du-forez"] = lo({ lede: "Gamay from volcanic and granite hills in the Loire department, the southernmost Loire vineyard.", cat: "AOC, red and rosé", rec: "2000 (VDQS earlier; specification 2011)", facts: [["Area", "About 70 ha"], ["Colors", "Rosé 85%, red 15%"], ["Grape", "Gamay"]], place: "The vineyards lie on granite and basalt slopes of the Forez mountains, west of the upper Loire near Boën.", rules: "Red and rosé from Gamay only.", glass: "Light, fresh, peppery Gamay and rosé.", producers: ["Domaine Verdier-Logel", "Cave des Vignerons Foréziens"] });
APXF["fr-cotes-d-auvergne"] = lo({ lede: "The vineyards of the Auvergne volcanoes around Clermont-Ferrand, promoted to AOC in 2011, with five village names.", cat: "AOC, red, rosé and white; five village names", rec: "2011 (modified 2013 and 2018)", facts: [["Area", "About 250 ha"], ["Colors", "Red 66%, rosé 19%, white 16%"], ["Grapes", "Red: Gamay, Pinot Noir. White: Chardonnay"], ["Village names", "Boudes, Chanturgue, Châteaugay, Corent, Madargues"]], place: "The vineyards lie on volcanic and limestone slopes in the Limagne plain around Clermont-Ferrand, below the Chaîne des Puys. Before phylloxera the Auvergne had tens of thousands of hectares of vines.", rules: "Five villages may add their name, each with its own style.", glass: "Light, fresh Gamay with peppery, volcanic notes; Corent is known for rosé.", producers: ["Domaine Miolanne", "Domaine Sauvat", "Cave Saint-Verny", "Domaine Pierre Goigoux"] });
function auv(name, o) { return lo({ lede: o.lede, cat: "AOC Côtes d'Auvergne with the village name " + name, rec: "2011", facts: [["Style", o.style]], place: o.place, rules: "One of five villages that may add their name to Côtes d'Auvergne.", glass: o.glass, producers: o.producers || [] }); }
